{% macro text(value) -%}{{ value | default('', true) | string | regex_replace('[\\r\\n]+', ' ') | e }}{%- endmacro %}
{% macro when(value) -%}{% set stamp = as_timestamp(value, none) %}{% if stamp is not none %}{{ stamp | timestamp_custom('%d %b, %H:%M', true) }}{% else %}Time not recorded{% endif %}{%- endmacro %}
{% set availability = states('sensor.homelab_alerts') %}
{% set items = state_attr('sensor.homelab_alerts', 'active') or [] %}
{% set items = items if items is sequence and items is not string and items is not mapping else [] %}
{% set total = availability | int(items | length) %}
{% set updated = state_attr('sensor.homelab_alerts', 'last_updated') %}
<div>
{% if availability == 'unknown' %}
<ha-alert alert-type="info">Waiting for the first server alert update. A clear status has not been received yet.</ha-alert>
{% elif availability == 'unavailable' %}
<ha-alert alert-type="warning">Server alerts are unavailable. This does not mean the servers are healthy. Check the alert bridge connection.</ha-alert>
{% else %}
<p><strong>{{ total }} active {{ 'alert' if total == 1 else 'alerts' }}</strong>{% if updated %}<br>Updated {{ when(updated) }}{% endif %}</p>
{% if total == 0 %}<p>No active server alerts.</p>{% endif %}
{% endif %}
{% if items | length > 0 %}
{% if availability in ['unknown', 'unavailable'] %}<p>Last recorded active alerts. Their current status is unconfirmed.</p>{% endif %}
{% for item in items[:50] if item is mapping %}
{% if loop.index == 11 %}<details><summary>Show {{ [items | length, 50] | min - 10 }} more active alerts</summary>{% endif %}
<p><strong>{{ text(item.get('title') or 'Server alert') }}</strong><br>{{ text(item.get('host') or 'Homelab') }} · {{ {'critical': 'Critical', 'warning': 'Warning', 'info': 'Info'}.get(item.get('severity'), 'Info') }}<br>{{ text(item.get('message')) }}<br>Started {{ when(item.get('started_at')) }}</p>
{% if not loop.last %}<hr>{% endif %}
{% endfor %}
{% if items | length > 10 %}</details>{% endif %}
{% if total > 50 %}<p>Showing the first 50 of {{ total }} active alerts, with critical alerts first.</p>{% elif total > items | length %}<p>Showing {{ items | length }} of {{ total }} active alerts.</p>{% endif %}
{% elif availability not in ['unknown', 'unavailable'] and total > 0 %}
<ha-alert alert-type="warning">Alert details have not arrived yet.</ha-alert>
{% endif %}
</div>

{% macro text(value) -%}{{ value | default('', true) | string | regex_replace('[\\r\\n]+', ' ') | e }}{%- endmacro %}
{% macro when(value) -%}{% set stamp = as_timestamp(value, none) %}{% if stamp is not none %}{{ stamp | timestamp_custom('%d %b, %H:%M', true) }}{% else %}Time not recorded{% endif %}{%- endmacro %}
{% set availability = states('sensor.homelab_alerts') %}
{% set items = state_attr('sensor.homelab_alerts', 'history') or [] %}
{% set items = items if items is sequence and items is not string and items is not mapping else [] %}
<div>
{% if availability in ['unknown', 'unavailable'] %}<p>The feed is unavailable. Any history below is the last recorded history.</p>{% endif %}
{% if items | length == 0 %}<p>No alert events recorded yet.</p>{% else %}
<p>Latest {{ [items | length, 50] | min }} events, newest first.</p>
{% for item in items[:50] if item is mapping %}
<p><strong>{{ text(item.get('title') or 'Server alert') }}</strong><br>{{ text(item.get('host') or 'Homelab') }} · {{ {'resolved': 'Resolved', 'firing': 'Firing'}.get(item.get('status'), 'Recorded') }} · {{ {'critical': 'Critical', 'warning': 'Warning', 'info': 'Info'}.get(item.get('severity'), 'Info') }}<br>{{ text(item.get('message')) }}<br>{{ when(item.get('time')) }}</p>
{% if not loop.last %}<hr>{% endif %}
{% endfor %}
{% endif %}
</div>
